Which words show up together in profile bios?
netNodes = (await FileAttachment("data/bio_network_nodes.csv").csv()).map(d =&gt; ({term: d.term, lean: +d.lean, degree: +d.degree, x: +d.x, y: +d.y, pole: d.pole === "true"}))
netEdges = (await FileAttachment("data/bio_network_edges.csv").csv()).map(d =&gt; ({source: d.source, target: d.target, weight: +d.weight}))
bioNetwork = {
  const W = Math.min(width, 760), H = Math.round(W * 0.7), pad = 28;
  const q = (k, p) =&gt; d3.quantile(netNodes.map(d =&gt; d[k]).sort(d3.ascending), p);
  const xs = d3.scaleLinear().domain([q("x", 0.02), q("x", 0.98)]).range([pad, W - pad]).clamp(true);
  const ys = d3.scaleLinear().domain([q("y", 0.02), q("y", 0.98)]).range([H - pad, pad + 10]).clamp(true);
  const color = d3.scaleDiverging([-0.09, 0, 0.13], d3.interpolateRgbBasis(["#2166AC", "#B8B8B8", "#B2182B"]));
  const r = d3.scaleSqrt().domain([0, d3.max(netNodes, d =&gt; d.degree)]).range([2.5, 11]);
  const adj = new Map(netNodes.map(d =&gt; [d.term, []]));
  netEdges.forEach(e =&gt; { adj.get(e.source).push([e.target, e.weight]); adj.get(e.target).push([e.source, e.weight]); });
  const topNbrs = t =&gt; adj.get(t).slice().sort((a, b) =&gt; b[1] - a[1]).map(d =&gt; d[0]);
  const byLean = netNodes.slice().sort((a, b) =&gt; Math.abs(b.lean) - Math.abs(a.lean)).slice(0, 18).map(d =&gt; d.term);
  const byDeg = netNodes.slice().sort((a, b) =&gt; b.degree - a.degree).slice(0, 8).map(d =&gt; d.term);
  const baseLabels = new Set([...byLean, ...byDeg, "liberal", "conservative"]);
  const leanText = d =&gt; d.pole ? `anchor for bios that name ${d.term} terms outright`
    : Math.abs(d.lean) &lt; 0.015 ? "near the middle"
    : `${Math.abs(d.lean) &gt; 0.05 ? "strongly " : ""}leans ${d.lean &gt; 0 ? "conservative" : "liberal"}`;

  const wrap = d3.create("div").style("position", "relative").style("max-width", `${W}px`);
  wrap.append("div").style("font-size", "13px").style("margin-bottom", "4px").html(
    `&lt;span style="color:#2166AC"&gt;●&lt;/span&gt; liberal-leaning &nbsp; &lt;span style="color:#B8B8B8"&gt;●&lt;/span&gt; in between &nbsp; &lt;span style="color:#B2182B"&gt;●&lt;/span&gt; conservative-leaning &nbsp; ▲ anchor &nbsp; &lt;span style="opacity:.7"&gt;Bigger dots appear with more words.&lt;/span&gt;`);
  const svg = wrap.append("svg").attr("viewBox", [0, 0, W, H]).attr("width", W).attr("height", H)
    .style("max-width", "100%").style("height", "auto").style("font-family", "Inter, sans-serif");
  const link = svg.append("g").selectAll("line").data(netEdges).join("line")
    .attr("x1", e =&gt; xs(netNodes.find(n =&gt; n.term === e.source).x)).attr("y1", e =&gt; ys(netNodes.find(n =&gt; n.term === e.source).y))
    .attr("x2", e =&gt; xs(netNodes.find(n =&gt; n.term === e.target).x)).attr("y2", e =&gt; ys(netNodes.find(n =&gt; n.term === e.target).y))
    .attr("stroke", "#8a8f98").attr("stroke-opacity", 0.07).attr("stroke-width", e =&gt; 0.5 + e.weight * 4);
  const node = svg.append("g").selectAll("path").data(netNodes).join("path")
    .attr("transform", d =&gt; `translate(${xs(d.x)},${ys(d.y)})`)
    .attr("d", d =&gt; d3.symbol(d.pole ? d3.symbolTriangle : d3.symbolCircle, Math.PI * r(d.degree) ** 2 * (d.pole ? 1.6 : 1))())
    .attr("fill", d =&gt; color(d.lean)).style("stroke", "var(--bs-body-bg)").attr("stroke-width", 0.8).style("cursor", "pointer");
  const label = svg.append("g").selectAll("text").data(netNodes).join("text")
    .attr("x", d =&gt; xs(d.x)).attr("y", d =&gt; ys(d.y) - r(d.degree) - 3).attr("text-anchor", "middle")
    .attr("font-size", d =&gt; d.pole ? 12.5 : 10.5).attr("font-weight", d =&gt; d.pole ? 700 : 400)
    .attr("fill", "currentColor").attr("paint-order", "stroke").style("stroke", "var(--bs-body-bg)").attr("stroke-width", 3)
    .style("pointer-events", "none").text(d =&gt; d.term).attr("opacity", d =&gt; baseLabels.has(d.term) ? 1 : 0);
  const tip = wrap.append("div").style("position", "absolute").style("pointer-events", "none").style("opacity", 0)
    .style("background", "var(--bs-body-bg)").style("border", "1px solid #D9CDB2").style("border-radius", "6px")
    .style("padding", "6px 9px").style("font-size", "13px").style("line-height", "1.35").style("max-width", "230px")
    .style("box-shadow", "0 2px 8px rgba(0,0,0,.15)");

  function focus(ev, d) {
    const nb = topNbrs(d.term), shown = new Set([d.term, ...nb.slice(0, 12)]), all = new Set([d.term, ...nb]);
    node.attr("opacity", o =&gt; all.has(o.term) ? 1 : 0.12);
    link.attr("stroke-opacity", e =&gt; e.source === d.term || e.target === d.term ? 0.45 : 0.015);
    label.attr("opacity", o =&gt; shown.has(o.term) ? 1 : 0);
    const x = xs(d.x), y = ys(d.y) + 20;
    tip.style("opacity", 1).style("left", `${Math.min(x + 12, W - 240)}px`).style("top", `${y}px`)
      .html(`&lt;b&gt;${d.term}&lt;/b&gt;&lt;br&gt;${leanText(d)}&lt;br&gt;appears alongside ${nb.length} other words&lt;br&gt;&lt;span style="opacity:.75"&gt;most often: ${nb.slice(0, 5).join(", ")}&lt;/span&gt;`);
  }
  function reset() {
    node.attr("opacity", 1); link.attr("stroke-opacity", 0.07);
    label.attr("opacity", d =&gt; baseLabels.has(d.term) ? 1 : 0); tip.style("opacity", 0);
  }
  node.on("mouseenter", focus).on("click", focus).on("mouseleave", reset);
  return wrap.node();
}
